time_t t;
struct tm *lt;

// Get current time (seconds since Epoch)
time(&t);

// Convert time_t to local broken-down time
// Returns pointer to static struct tm
lt = localtime(&t);

// Access components of struct tm
// tm_year: Years since 1900
int current_year = lt->tm_year + 1900;
int current_day = lt->tm_mday;

// tm_hour (0-23), tm_isdst (DST flag)
int current_hour = lt->tm_hour;
int is_dst = lt->tm_isdst;

// Note: Output must be immediately copied
// Use 'gmtime' for UTC equivalent.
